import sys
import requests
import csv
from urllib.parse import urlparse
import os

def is_valid_url(url):
    """Validate URL to prevent open redirects, SSRF, and malformed URLs."""
    try:
        result = urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def sanitize_path(path):
    """Sanitize file path to prevent directory traversal attacks."""
    # Normalize path and remove any path traversal components
    path = os.path.normpath(path)
    # Ensure the path is absolute and doesn't contain relative path components
    if not path.startswith('/'):
        path = '/' + path
    # Remove any path components that are dangerous
    dangerous_parts = ['..', '.']
    for part in dangerous_parts:
        if part in path:
            return None
    # Ensure the path is within a safe directory (e.g., current directory only)
    if '..' in path or os.path.isabs(path) and not path.startswith('/'):
        return None
    return path

def main():
    # Read the path to the text file from standard input
    file_path_input = sys.stdin.readline().strip()

    if not file_path_input:
        print("Error: No file path provided.", file=sys.stderr)
        sys.exit(1)

    # Sanitize the file path to prevent path traversal
    sanitized_path = sanitize_path(file_path_input)
    if not sanitized_path:
        print("Error: Invalid or dangerous file path provided.", file=sys.stderr)
        sys.exit(1)

    # Verify the sanitized path is within the expected directory
    if not os.path.exists(sanitized_path):
        print(f"Error: File '{sanitized_path}' not found.", file=sys.stderr)
        sys.exit(1)

    # Create a summary CSV file
    with open('summary.csv', 'w', newline='') as csvfile:
        fieldnames = ['url', 'status_code', 'content_length']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()

        # Open and read the input file
        try:
            with open(sanitized_path, 'r', encoding='utf-8') as file:
                for line_num, line in enumerate(file, 1):
                    url = line.strip()
                    if not url:
                        continue

                    # Validate the URL to prevent open redirects and SSRF
                    if not is_valid_url(url):
                        writer.writerow({
                            'url': url,
                            'status_code': 0,
                            'content_length': 0
                        })
                        continue

                    try:
                        response = requests.get(url, timeout=10)
                        content_length = response.headers.get('content-length', '0')
                        # Ensure content_length is a number
                        try:
                            content_length = int(content_length)
                        except (ValueError, TypeError):
                            content_length = 0

                        writer.writerow({
                            'url': url,
                            'status_code': response.status_code,
                            'content_length': content_length
                        })
                    except requests.RequestException:
                        writer.writerow({
                            'url': url,
                            'status_code': 0,
                            'content_length': 0
                        })
        except PermissionError:
            print(f"Error: Permission denied when reading '{sanitized_path}'.", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()

import json
import sys
import requests
import os
from typing import Dict, Any, List
from pathlib import Path

def validate_url(url: str) -> bool:
    """Validate URL to prevent open redirects, path traversal, and SSRF."""
    if not url.startswith(('http://', 'https://')):
        return False
    # Allow only basic domain and path, disallow relative paths or traversal
    if '..' in url or '/./' in url or '/../' in url:
        return False
    # Limit path length to prevent excessive requests
    if len(url) > 2048:
        return False
    return True

def validate_config(config: Dict[str, Any]) -> bool:
    """Validate configuration structure and content."""
    if not isinstance(config, dict):
        return False
    if "sources" not in config or not isinstance(config["sources"], list):
        return False
    if "cache_file" not in config or not isinstance(config["cache_file"], str):
        return False

    for source in config["sources"]:
        if not isinstance(source, dict):
            return False
        if "name" not in source or "url" not in source:
            return False
        if not isinstance(source["name"], str) or not isinstance(source["url"], str):
            return False
        if len(source["name"]) == 0 or len(source["url"]) == 0:
            return False
    return True

def sanitize_name(name: str) -> str:
    """Sanitize name to prevent injection attacks."""
    if not isinstance(name, str):
        return ""
    # Remove any characters that could be used for injection
    sanitized = name.strip()
    # Prevent use of dangerous names
    if any(part in sanitized for part in ("__import__", "__dict__", "__class__", "system", "os", "eval", "exec")):
        return ""
    return sanitized

def fetch_metric(url: str) -> float:
    """Fetch metric from remote URL with validation."""
    if not validate_url(url):
        raise ValueError(f"Invalid or unsafe URL: {url}")
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict) or "metric" not in data:
            raise ValueError("Invalid response format")
        metric_value = data["metric"]
        if not isinstance(metric_value, (int, float)):
            raise ValueError("Metric must be a number")
        return float(metric_value)
    except Exception as e:
        raise RuntimeError(f"Failed to fetch metric from {url}: {str(e)}")

def save_cache(cache_file: str, name_to_metric: Dict[str, float], mean: float):
    """Save cache data securely with integrity checks."""
    cache_data = {
        "name_to_metric": name_to_metric,
        "mean": mean
    }
    cache_path = Path(cache_file)
    # Ensure directory exists
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    # Write in a way that prevents overwriting by other processes
    # Use a temporary file and rename after write
    temp_file = cache_path.with_suffix(cache_path.suffix + ".tmp")
    try:
        with open(temp_file, 'wb') as f:
            # Use a secure serialization format (JSON) with strict schema
            json_data = json.dumps(cache_data, separators=(',', ':'), ensure_ascii=True)
            f.write(json_data.encode('utf-8'))
        # Replace original file atomically
        temp_file.rename(cache_path)
    except Exception as e:
        # Clean up temp file if creation fails
        if temp_file.exists():
            temp_file.unlink()
        raise RuntimeError(f"Failed to save cache: {str(e)}")

def load_cache(cache_file: str) -> Dict[str, Any]:
    """Load cache data with strict validation and integrity checks."""
    cache_path = Path(cache_file)
    if not cache_path.exists():
        return None

    # Validate file integrity: check if it's a valid JSON file
    try:
        with open(cache_path, 'rb') as f:
            data = f.read()
            if not data:
                return None
            # Validate JSON structure
            json_data = data.decode('utf-8')
            parsed = json.loads(json_data)
            # Validate schema
            if not isinstance(parsed, dict):
                return None
            if "name_to_metric" not in parsed or "mean" not in parsed:
                return None
            if not isinstance(parsed["name_to_metric"], dict):
                return None
            if not isinstance(parsed["mean"], (int, float)):
                return None
            return parsed
    except Exception as e:
        # Log error but return None to indicate failure
        return None

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_summary.py <config_file> [--offline]")
        sys.exit(1)

    config_path = sys.argv[1]
    offline_flag = '--offline' in sys.argv

    # Validate command-line argument
    if not Path(config_path).is_absolute():
        config_path = os.path.abspath(config_path)

    # Load and validate configuration
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading configuration file: {str(e)}", file=sys.stderr)
        sys.exit(1)

    if not validate_config(config):
        print("Invalid configuration file structure", file=sys.stderr)
        sys.exit(1)

    sources = config.get("sources", [])
    cache_file = config.get("cache_file", "./cache.bin")

    if offline_flag:
        cached_data = load_cache(cache_file)
        if cached_data is None:
            print("no cache available", file=sys.stderr)
            sys.exit(1)

        name_to_metric = cached_data["name_to_metric"]
        mean = cached_data["mean"]

        for source in sources:
            name = source["name"]
            sanitized_name = sanitize_name(name)
            if sanitized_name and sanitized_name in name_to_metric:
                print(f"{sanitized_name}: {name_to_metric[sanitized_name]}")
        print(f"mean: {mean}")
    else:
        name_to_metric = {}
        for source in sources:
            name = source["name"]
            url = source["url"]
            sanitized_name = sanitize_name(name)
            if not sanitized_name:
                print(f"Invalid source name: {name}", file=sys.stderr)
                continue
            try:
                metric = fetch_metric(url)
                name_to_metric[sanitized_name] = metric
            except Exception as e:
                print(f"Error fetching {url}: {str(e)}", file=sys.stderr)

        mean = sum(name_to_metric.values()) / len(name_to_metric) if name_to_metric else 0.0

        # Save to cache with integrity and atomicity
        save_cache(cache_file, name_to_metric, mean)

        # Print results
        for source in sources:
            name = source["name"]
            sanitized_name = sanitize_name(name)
            if sanitized_name in name_to_metric:
                print(f"{sanitized_name}: {name_to_metric[sanitized_name]}")
        print(f"mean: {mean}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json
import re

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    overrides = sys.argv[2:]

    # Validate and sanitize overrides
    valid_chars = r'^[a-zA-Z0-9_][a-zA-Z0-9._-]*$'
    config_dict = {}

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML file: {e}")
    except FileNotFoundError:
        sys.exit(f"File not found: {xml_path}")

    # Build initial dictionary from XML entries
    for entry in root:
        if entry.tag == 'entry':
            name = entry.get('name')
            value = entry.get('value')
            if name and value:
                # Validate name and value for safety
                if re.match(valid_chars, name):
                    config_dict[name] = value

    # Apply command-line overrides with validation
    for override in overrides:
        if '=' not in override:
            sys.exit(f"Invalid override format: {override}. Must be 'name=value'.")

        name, value = override.split('=', 1)

        # Validate name and value
        if not name or not re.match(valid_chars, name):
            sys.exit(f"Invalid name in override: {name}. Names must contain only alphanumeric, underscore, dot, and hyphen, and start with alphanumeric.")

        # Validate value - ensure it doesn't contain dangerous sequences
        # This is a basic check to prevent shell injection or path traversal
        # More sophisticated checks can be added based on use case
        if re.search(r'[\x00-\x1F\x7F]|;|&|\$|\`|`|\'|\"|\\|\x00', value):
            sys.exit(f"Invalid value in override: {value}. Contains potentially dangerous characters.")

        config_dict[name] = value

    # Print the result as JSON
    print(json.dumps(config_dict, indent=2))

if __name__ == "__main__":
    main()

import sys
import requests
import html

def main():
    if len(sys.argv) != 2:
        print("ERROR: Missing username argument", file=sys.stderr)
        sys.exit(1)

    username = sys.argv[1]

    # Validate username: only allow alphanumeric, underscore, hyphen, and must not be empty or too long
    if not username or not username.strip():
        print("ERROR: Username cannot be empty", file=sys.stderr)
        sys.exit(1)

    # Validate username format: only allow alphanumeric, underscore, hyphen
    if not all(c.isalnum() or c in ['_', '-'] for c in username):
        print("ERROR: Username contains invalid characters", file=sys.stderr)
        sys.exit(1)

    # Limit username length to prevent abuse (GitHub usernames are typically under 39 chars)
    if len(username) > 39:
        print("ERROR: Username is too long", file=sys.stderr)
        sys.exit(1)

    user_url = f"https://api.github.com/users/{username}"
    repos_url = f"https://api.github.com/users/{username}/repos"

    try:
        # Get user profile
        user_response = requests.get(user_url, timeout=10)
        if user_response.status_code != 200:
            print(f"ERROR: Failed to retrieve user data (status {user_response.status_code})", file=sys.stderr)
            sys.exit(1)

        user_data = user_response.json()

        # Get repositories
        repos_response = requests.get(repos_url, timeout=10)
        if repos_response.status_code != 200:
            print(f"ERROR: Failed to retrieve repositories (status {repos_response.status_code})", file=sys.stderr)
            sys.exit(1)

        repos_data = repos_response.json()

        # Build HTML with proper escaping to prevent XSS
        html = f"""<!DOCTYPE html>
<html>
<head>
    <title>GitHub Report: {html.escape(username)}</title>
    <style>
        body {{
            font-family: Arial, sans-serif;
            margin: 20px;
        }}
        h1, h2 {{
            color: #2c3e50;
        }}
        ul {{
            list-style-type: none;
            padding: 0;
        }}
        li {{
            border: 1px solid #3498db;
            margin: 10px 0;
            padding: 10px;
            border-radius: 5px;
            background-color: #f9f9f9;
        }}
        li a {{
            text-decoration: none;
            color: #2980b9;
            font-weight: bold;
        }}
        li a:hover {{
            text-decoration: underline;
        }}
    </style>
</head>
<body>
    <h1>{html.escape(user_data['login'])}</h1>

    <div style="margin-bottom: 20px;">
        <p><strong>Display Name:</strong> {html.escape(user_data['name'] or 'N/A')}</p>
        <p><strong>Bio:</strong> {html.escape(user_data['bio'] or 'N/A')}</p>
        <img src="{user_data['avatar_url']}" alt="Avatar" style="width: 100px; height: 100px; border-radius: 50%; margin: 10px 0;">
    </div>

    <h2>Public Repositories</h2>
    <ul>
    """

        for repo in repos_data:
            repo_name = html.escape(repo["name"])
            repo_url = repo["html_url"]
            star_count = repo["stargazers_count"]
            html += f'<li><a href="{repo_url}">{repo_name}</a> - {star_count} stars</li>\n'

        html += """    </ul>
</body>
</html>"""

        print(html)

    except requests.exceptions.RequestException as e:
        print(f"ERROR: Network request failed: {e}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"ERROR: Failed to parse JSON response: {e}", file=sys.stderr)
        sys.exit(1)

