import sys
import json
import xml.etree.ElementTree as ET
import ast

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    # Load JSON data
    with open(json_path, 'r') as f:
        data = json.load(f)

    # Validate that data is a dictionary
    if not isinstance(data, dict):
        sys.exit(1)

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except Exception as e:
        sys.exit(1)

    # Validate XML structure
    if root.tag != 'calculations':
        sys.exit(1)

    # Process each calc element in order
    for calc in root.findall('calc'):
        name = calc.get('name')
        expr = calc.get('expr')

        if not name or not expr:
            continue

        # Validate name is a valid string key (no special characters that could be used for injection)
        if not isinstance(name, str) or not name.replace('_', '').isalnum():
            continue

        # Validate expression syntax using AST
        try:
            # Parse expression to ensure it's safe
            tree = ast.parse(expr, mode='eval')

            # Validate that the expression only uses safe operations
            # Only allow literals, basic arithmetic, and access to data keys
            for node in ast.walk(tree):
                if isinstance(node, ast.Name):
                    # Check if the name is a valid key in data (only alphanumeric or underscore)
                    if not node.id.replace('_', '').isalnum():
                        raise ValueError("Invalid expression")
                elif isinstance(node, ast.Attribute):
                    # Attribute access is only allowed on data keys
                    if not isinstance(node.value, ast.Name) or node.value.id != 'data':
                        raise ValueError("Invalid expression")
                    if not node.attr.replace('_', '').isalnum():
                        raise ValueError("Invalid expression")
                elif isinstance(node, ast.Call):
                    # No function calls allowed
                    raise ValueError("Function calls not allowed")
                elif isinstance(node, ast.Compare):
                    # Only allow comparisons with literals
                    if len(node.ops) != 1 or not isinstance(node.ops[0], ast.Eq):
                        raise ValueError("Invalid expression")
                elif isinstance(node, ast.BinOp):
                    # Only allow basic arithmetic
                    if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod)):
                        raise ValueError("Invalid expression")
                elif isinstance(node, ast.UnaryOp):
                    # Only allow + and - unary operations
                    if not isinstance(node.op, (ast.USub, ast.UAdd)):
                        raise ValueError("Invalid expression")
                elif isinstance(node, ast.Str):
                    # String literals are allowed
                    pass
                elif isinstance(node, ast.Num):
                    # Numbers are allowed
                    pass
                elif isinstance(node, ast.List):
                    # Lists are not allowed
                    raise ValueError("Lists not allowed")
                elif isinstance(node, ast.Dict):
                    # Dictionaries are not allowed
                    raise ValueError("Dictionaries not allowed")

        except (SyntaxError, ValueError) as e:
            sys.stderr.write(f"ERROR name={name} expr={expr}\n")
            continue

        # Evaluate expression safely in a restricted context
        try:
            # Only allow access to data dictionary and built-in literals
            safe_globals = {
                '__builtins__': {
                    'abs': abs, 'round': round, 'int': int, 'float': float,
                    'str': str, 'len': len, 'type': type, 'list': list,
                    'dict': dict, 'tuple': tuple, 'set': set, 'bool': bool
                }
            }

            # Evaluate expression with only data and safe built-ins
            result = eval(expr, safe_globals, data)

            # Ensure result is a valid type (primitive)
            if not isinstance(result, (int, float, str, bool, type(None))):
                # If result is not a primitive, skip it
                continue

            data[name] = result

        except Exception as e:
            sys.stderr.write(f"ERROR name={name} expr={expr}\n")

    # Output final JSON
    print(json.dumps(data))

