import sys
import json
import requests
from xml.etree import ElementTree as ET
from urllib.parse import urlparse, urljoin
from typing import Dict, List, Optional
import urllib3

# Disable insecure warnings for SSL (if needed) and set a reasonable timeout
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def parse_config(xml_path: str) -> List[Dict[str, str]]:
    """Parse the XML configuration file safely."""
    try:
        with open(xml_path, 'r', encoding='utf-8') as file:
            content = file.read()
    except FileNotFoundError:
        sys.exit(f"Configuration file {xml_path} not found.")
    except PermissionError:
        sys.exit(f"Permission denied when reading configuration file {xml_path}.")

    try:
        root = ET.fromstring(content)
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML configuration: {e}")

    feeds = []
    for feed_elem in root.findall('feed'):
        url = feed_elem.get('url')
        name = feed_elem.get('name')

        if not url:
            sys.exit("Missing 'url' attribute in feed element.")

        # Validate URL format using a basic scheme and domain check
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            sys.exit(f"Invalid URL format: {url}")

        # Validate that the URL does not contain potentially dangerous paths or parameters
        # This is a basic check; in production, use a more robust URL validation library
        if '..' in parsed_url.path or '//' in parsed_url.path or ' ' in parsed_url.path:
            sys.exit(f"URL contains unsafe path components: {url}")

        if not name:
            name = url

        feeds.append({'url': url, 'name': name})

    return feeds

def is_valid_rss_content(content: bytes) -> bool:
    """Check if the content is likely to be valid RSS XML."""
    if not content or len(content) == 0:
        return False

    # Check for basic RSS XML structure (presence of RSS or channel)
    try:
        root = ET.fromstring(content)
        # Check for common RSS elements
        if root.tag in ['rss', 'channel']:
            return True
    except ET.ParseError:
        pass

    return False

def fetch_feed_titles(feeds: List[Dict[str, str]]) -> Dict[str, List[str]]:
    """Fetch titles from RSS feeds with security mitigations."""
    result: Dict[str, List[str]] = {}

    # Use a single-threaded approach to avoid overwhelming servers
    for feed in feeds:
        url = feed['url']
        name = feed['name']

        try:
            # Set a reasonable timeout to prevent hanging
            response = requests.get(url, timeout=10, verify=True, allow_redirects=False)

            # Check if the response is a redirect or has a non-200 status
            if response.status_code != 200:
                result[name] = []
                continue

            # Check if the response content is valid RSS XML
            content = response.content
            if not is_valid_rss_content(content):
                result[name] = []
                continue

            # Parse the XML with security settings
            try:
                root = ET.fromstring(content)
                titles = []
                # Use a safe XPath to find items and titles
                for item in root.findall('.//item'):
                    title_elem = item.find('title')
                    if title_elem is not None and title_elem.text:
                        titles.append(title_elem.text.strip())
                result[name] = titles
            except ET.ParseError:
                # If parsing fails, return empty list
                result[name] = []

        except requests.RequestException as e:
            # Log or handle request exceptions (e.g., timeout, connection error)
            result[name] = []

    return result

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: python fetch_feed_titles.py path/to/config.xml")

    config_path = sys.argv[1]
    feeds = parse_config(config_path)
    titles_data = fetch_feed_titles(feeds)
    print(json.dumps(titles_data, indent=2))

if __name__ == "__main__":
    main()

import sys
import json
import requests
import os
from urllib.parse import urlparse, urljoin

def main(config_path):
    # Read and decode configuration
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print("Error reading configuration file.", file=sys.stderr)
        sys.exit(1)

    api_url = config.get("api_url")
    page_title = config.get("page_title")

    if not api_url or not page_title:
        print("Missing required configuration keys.", file=sys.stderr)
        sys.exit(1)

    # Validate and sanitize page_title to prevent HTML injection
    if not isinstance(page_title, str):
        page_title = ""
    # Remove any potentially dangerous characters or tags
    safe_page_title = page_title.strip()
    # Ensure only safe characters are used (no script, style, etc.)
    safe_page_title = safe_page_title.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')

    # Validate and sanitize api_url to prevent open redirects and SSRF
    parsed_url = urlparse(api_url)
    if not parsed_url.scheme or not parsed_url.netloc:
        print("Invalid API URL format.", file=sys.stderr)
        sys.exit(1)

    # Ensure the API URL is from a trusted domain (basic check)
    # This is a simplified check; in production, use a whitelist of allowed domains
    allowed_domains = ["example.com"]  # This should be configured securely
    if parsed_url.netloc.lower() not in [domain.lower() for domain in allowed_domains]:
        print("API URL from unauthorized domain.", file=sys.stderr)
        sys.exit(1)

    # Fetch articles from API or use cache
    cache_file = "news_cache.json"
    articles = []

    # Try to fetch from API
    try:
        response = requests.get(api_url, timeout=10)
        response.raise_for_status()
        data = response.json()

        # Validate data structure
        if isinstance(data, list):
            # Filter and sanitize each article
            sanitized_articles = []
            for item in data:
                if isinstance(item, dict):
                    title = item.get("title", "").strip()
                    url = item.get("url", "").strip()
                    # Sanitize title and url
                    if title and url:
                        # Remove dangerous HTML tags from title
                        title = title.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')
                        # Validate URL format
                        if is_safe_url(url):
                            sanitized_articles.append({
                                "title": title,
                                "url": url
                            })
            articles = sanitized_articles
        else:
            print("API returned invalid data format.", file=sys.stderr)
    except (requests.RequestException, json.JSONDecodeError) as e:
        # If API request fails, try to load from cache
        pass

    # If API failed, try to load from cache
    if not articles:
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                cache_data = json.load(f)
            if isinstance(cache_data, list):
                # Filter and sanitize cached articles
                sanitized_articles = []
                for item in cache_data:
                    if isinstance(item, dict):
                        title = item.get("title", "").strip()
                        url = item.get("url", "").strip()
                        if title and url:
                            title = title.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')
                            if is_safe_url(url):
                                sanitized_articles.append({
                                    "title": title,
                                    "url": url
                                })
                articles = sanitized_articles
        except (FileNotFoundError, json.JSONDecodeError):
            # Cache file missing or invalid, use empty list
            pass

    # Write articles to cache if we have them
    if articles:
        try:
            with open(cache_file, 'w', encoding='utf-8') as f:
                json.dump(articles, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Error writing cache file: {e}", file=sys.stderr)

    # Generate HTML output with safe sanitization
    html = [
        "<!DOCTYPE html>",
        "<html>",
        "  <head>",
        f"    <title>{safe_page_title}</title>",
        "  </head>",
        "  <body>",
        f"    <h1>{safe_page_title}</h1>",
        "    <ul>"
    ]

    for article in articles:
        title = article.get("title", "")
        url = article.get("url", "")
        if title and url:
            # Ensure URL is safe and properly formatted
            html.append(f"      <li><a href='{url}' target='_blank'>{title}</a></li>")

    html.append("    </ul>")
    html.append("  </body>")
    html.append("</html>")

    print("\n".join(html))

def is_safe_url(url):
    """Check if URL is safe by validating against known dangerous patterns."""
    # Check for common XSS vectors
    dangerous_patterns = [
        'javascript:', 'vbscript:', 'data:', 'about:', 'mailto:',
        'exec', 'eval', 'document.write', 'window.open', 'onload'
    ]

    for pattern in dangerous_patterns:
        if pattern in url.lower():
            return False

    # Validate basic URL structure
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except Exception:
        return False

