    if len(sys.argv) != 2:
        print("Usage: python news_page.py CONFIG_PATH", file=sys.stderr)
        sys.exit(1)
    main(sys.argv[1])

import sys
import json
import os
from typing import List, Dict, Any
import ast

def fetch_and_cache_records(data_url: str, use_cache: bool) -> List[Dict[str, Any]]:
    cache_file = '.remote_eval_cache'

    if use_cache and os.path.exists(cache_file):
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                records = json.load(f)
                return records
        except (json.JSONDecodeError, IOError) as e:
            # If cache is corrupted or inaccessible, fall back to fetching
            pass

    # Fetch from URL
    try:
        import requests
        response = requests.get(data_url, timeout=10)
        response.raise_for_status()
        body = response.text
    except requests.RequestException as e:
        print(f"Error fetching data from {data_url}: {e}", file=sys.stderr)
        sys.exit(1)

    # Parse newline-delimited JSON
    records = []
    for line in body.strip().split('\n'):
        line = line.strip()
        if line:
            try:
                record = json.loads(line)
                # Validate required fields
                if not all(k in record for k in ["id", "expression", "x"]):
                    print(f"Error: Missing required field(s) in record: {record}", file=sys.stderr)
                    continue
                # Validate types
                if not isinstance(record["id"], str):
                    print(f"Error: 'id' must be a string", file=sys.stderr)
                    continue
                if not isinstance(record["expression"], str):
                    print(f"Error: 'expression' must be a string", file=sys.stderr)
                    continue
                if not isinstance(record["x"], (int, float)):
                    print(f"Error: 'x' must be a number", file=sys.stderr)
                    continue
                records.append(record)
            except json.JSONDecodeError as e:
                print(f"Error parsing JSON line: {e}", file=sys.stderr)
                continue

    # Cache the records if not using cache
    if not use_cache:
        try:
            with open(cache_file, 'w', encoding='utf-8') as f:
                json.dump(records, f, ensure_ascii=False, indent=None)
        except IOError as e:
            print(f"Error writing to cache file: {e}", file=sys.stderr)
            sys.exit(1)

    return records

def evaluate_records(records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    results = []
    for record in records:
        try:
            x = record["x"]
            expression = record["expression"]

            # Validate expression syntax using AST
            tree = ast.parse(expression, mode='eval')

            # Check for dangerous operations
            for node in ast.walk(tree):
                if isinstance(node, (ast.Call, ast.Name, ast.Attribute)):
                    # Check for dangerous functions
                    if isinstance(node, ast.Call):
                        func_name = node.func.id if isinstance(node.func, ast.Name) else None
                        if func_name in ['os', 'subprocess', 'eval', 'exec', 'open', 'import']:
                            raise ValueError(f"Expression contains dangerous function: {func_name}")
                    elif isinstance(node, ast.Attribute):
                        attr_name = node.attr
                        if attr_name in ['system', 'popen', 'exec', 'read', 'write']:
                            raise ValueError(f"Expression contains dangerous attribute: {attr_name}")

            # Safe evaluation using ast.literal_eval-like logic
            # We only allow basic arithmetic and expressions with x
            # We validate the AST structure to ensure it's safe
            # We use eval with a restricted namespace
            safe_namespace = {"x": x}
            result = eval(expression, safe_namespace, {})

            # Create output record
            output_record = {
                "id": record["id"],
                "expression": record["expression"],
                "x": record["x"],
                "result": result
            }
            results.append(output_record)

        except (SyntaxError, ValueError, Exception) as e:
            print(f"Error evaluating expression: {e}", file=sys.stderr)
            # If evaluation fails, create a record with result as None
            output_record = {
                "id": record["id"],
                "expression": record["expression"],
                "x": record["x"],
                "result": None
            }
            results.append(output_record)

    return results

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_eval.py <DATA_URL> [--use-cache]", file=sys.stderr)
        sys.exit(1)

    data_url = sys.argv[1]
    use_cache = '--use-cache' in sys.argv

    records = fetch_and_cache_records(data_url, use_cache)

    output_records = evaluate_records(records)

    # Output each record as newline-delimited JSON
    for record in output_records:
        print(json.dumps(record, ensure_ascii=False))

if __name__ == '__main__':
    main()

import sys
import xml.etree.ElementTree as ET
import os
import requests
from urllib.parse import urljoin, urlparse

def load_config():
    try:
        tree = ET.parse('services.xml')
        root = tree.getroot()
        services = {}
        for service in root.findall('service'):
            name = service.get('name')
            base_url = service.get('base_url')
            token_env = service.get('token_env')
            if name and base_url and token_env:
                # Validate base_url format: must have a scheme and netloc
                parsed = urlparse(base_url)
                if not parsed.scheme or not parsed.netloc:
                    continue
                services[name] = {
                    'base_url': base_url,
                    'token_env': token_env
                }
        return services
    except FileNotFoundError:
        return {}
    except Exception as e:
        # Log error but don't exit, return empty dict
        return {}

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    service_name = sys.argv[1]
    path = sys.argv[2]

    services = load_config()
    if service_name not in services:
        print(f"Unknown service: {service_name}")
        sys.exit(1)

    service = services[service_name]
    token_env = service['token_env']
    token = os.getenv(token_env)

    if not token or token == "":
        print(f"Missing token for service: {service_name}")
        sys.exit(1)

    base_url = service['base_url']

    # Validate and sanitize the path to prevent path traversal
    # Only allow absolute paths or paths that start with a forward slash
    if not path.startswith('/'):
        print(f"Invalid path: {path}")
        sys.exit(1)

    # Use urljoin to safely combine base_url and path, preventing path traversal
    final_url = urljoin(base_url, path)

    try:
        response = requests.get(final_url, headers={'Authorization': f'Bearer {token}'}, timeout=10)
        print(f"URL: {final_url}")
        print(f"Status: {response.status_code}")
        if response.content:
            try:
                body = response.text
                print(body)
            except UnicodeDecodeError:
                # Fallback to latin1 encoding with replacement for non-text content
                print(response.content.decode('latin1', errors='replace'))
        else:
            print("")
    except requests.exceptions.RequestException as e:
        # Log the error but do not expose detailed information
        print(f"URL: {final_url}")
        print(f"Status: 500")
        print("Error occurred during request")

if __name__ == "__main__":
    main()

import sys
import time
import json
import os
import requests

def fetch_users():
    token = os.getenv('SERVICE_ACCESS_TOKEN')
    if not token or not token.strip():
        print("SERVICE_ACCESS_TOKEN not set", file=sys.stderr)
        sys.exit(1)

    user_ids = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            # Validate user ID: must be non-empty, contain only alphanumeric and underscore, and not contain path traversal patterns
            if not line.isalnum() and not any(c.isalnum() or c in '_-' for c in line):
                print(f"INVALID USER ID: {line}", file=sys.stderr)
                continue
            if '..' in line or '/' in line or '\\\\' in line or '\\/' in line:
                print(f"INVALID USER ID: {line}", file=sys.stderr)
                continue
            user_ids.append(line)

    if not user_ids:
        sys.exit(0)

    # Throttle: at most 2 requests per second (0.5 seconds between requests)
    last_request_time = 0
    results = []
    errors = []

    for user_id in user_ids:
        # Wait until it's time to make the next request
        current_time = time.time()
        if current_time - last_request_time < 0.5:
            sleep_duration = 0.5 - (current_time - last_request_time)
            time.sleep(sleep_duration)

        url = f"https://example.com/api/users/{user_id}"
        headers = {
            "Authorization": f"Bearer {token}"
        }

        try:
            response = requests.get(url, headers=headers, timeout=5)
            if response.status_code // 100 == 2:  # 2xx status code
                try:
                    data = response.json()
                    # Validate required fields exist and are strings
                    if not isinstance(data, dict):
                        errors.append(user_id)
                        continue
                    if 'id' not in data or 'name' not in data or 'email' not in data:
                        errors.append(user_id)
                        continue
                    if not isinstance(data['id'], str) or not isinstance(data['name'], str) or not isinstance(data['email'], str):
                        errors.append(user_id)
                        continue
                    results.append((data['id'], data['name'], data['email']))
                except json.JSONDecodeError:
                    errors.append(user_id)
            else:
                errors.append(user_id)
        except requests.exceptions.RequestException as e:
            errors.append(user_id)

        last_request_time = time.time()

    # Output successful results in the same order as input
    for result in results:
        print(f"{result[0]}\t{result[1]}\t{result[2]}")

    # Output failed user IDs to stderr
    for error in errors:
        print(f"FAILED {error}", file=sys.stderr)

    # Exit with 0 if at least one request was attempted
    sys.exit(0)

if __name__ == "__main__":
    fetch_users()

import sys
import requests
import xml.etree.ElementTree as ET
import json
from urllib.parse import urlparse, parse_qs
import re

def is_valid_url(url):
    """Validate URL format to prevent open redirects and malicious content."""
    if not url or not isinstance(url, str):
        return False

    # Basic schema validation
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return False

    # Prevent protocol spoofing (e.g., javascript:, data:, etc.)
    if parsed.scheme in ['javascript', 'data', 'mailto', 'tel', 'news', 'ftp']:
        return False

    # Prevent open redirects by checking for suspicious query parameters
    # This is a simplified check; in production, more robust validation is needed
    query_params = parse_qs(parsed.query)
    # Check for common redirect patterns (e.g., redirect, to, go, url)
    redirect_keywords = ['redirect', 'to', 'go', 'url', 'next', 'target']
    for kw in redirect_keywords:
        if kw in query_params:
            return False

    # Prevent malformed or suspicious characters
    # Allow only standard URL characters
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*://', url):
        return False

    return True

def parse_xml_safely(xml_content):
    """Parse XML content safely by disabling external entity processing."""
    try:
        # Parse XML with disabled external entities
        parser = ET.XMLParser(encoding='utf-8', resolve_entities=False)
        root = ET.fromstring(xml_content, parser=parser)
        return root
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML content: {str(e)}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
