        root = parse_xml_safely(xml_content)
    except ValueError as e:
        sys.exit(1)

    endpoints = {}
    for endpoint_elem in root.findall('endpoint'):
        name = endpoint_elem.get('name')
        url = endpoint_elem.get('url')

        if not name or not url:
            continue

        # Validate URL before making request
        if not is_valid_url(url):
            # Log warning or skip, but still include in output with null status and empty body
            endpoints[name] = {
                "url": url,
                "status": None,
                "body": ""
            }
            continue

        endpoints[name] = {
            "url": url,
            "status": None,
            "body": ""
        }

        try:
