import sys
import xml.etree.ElementTree as ET
import time
import requests
from urllib.parse import urlparse, urljoin
import re

def load_config(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()

        # Validate root element and required children
        if root.tag != 'config':
            raise ValueError("Root element must be 'config'")

        limits_elem = root.find('limits')
        if limits_elem is None:
            raise ValueError("Missing 'limits' element in config")

        min_interval_str = limits_elem.get('min_interval_seconds')
        if min_interval_str is None:
            raise ValueError("min_interval_seconds attribute missing in limits")

        try:
            min_interval = float(min_interval_str)
            if min_interval < 0:
                raise ValueError("min_interval_seconds must be non-negative")
        except ValueError as e:
            raise ValueError(f"Invalid min_interval_seconds value: {min_interval_str}") from e

        services = {}
        services_elem = root.find('services')
        if services_elem is None:
            raise ValueError("Missing 'services' element in config")

        for service_elem in services_elem.findall('service'):
            name = service_elem.get('name')
            base_url = service_elem.get('base_url')

            if not name or not base_url:
                continue

            # Validate service name and base URL
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
                raise ValueError(f"Invalid service name: {name}")

            # Validate base URL format
            parsed = urlparse(base_url)
            if not parsed.scheme or not parsed.netloc:
                raise ValueError(f"Invalid base URL format: {base_url}")

            # Ensure it's a secure protocol (HTTPS only)
            if parsed.scheme not in ('https', 'http'):
                raise ValueError(f"Base URL must use HTTPS or HTTP: {base_url}")

            # Prevent internal or local access
            if parsed.netloc.lower() in ('localhost', '127.0.0.1', '0.0.0.0'):
                raise ValueError(f"Base URL cannot be internal: {base_url}")

            services[name] = base_url

        return min_interval, services

    except ET.ParseError as e:
        raise ValueError(f"Invalid XML format in configuration file: {e}")
    except Exception as e:
        raise ValueError(f"Error loading configuration: {e}")

def is_valid_item_id(item_id):
    """Validate item_id to prevent path traversal and excessive length"""
    if not item_id:
        return False
    # Limit length to prevent resource exhaustion
    if len(item_id) > 1024:
        return False
    # Prevent path traversal attempts
    if '..' in item_id or '/' in item_id or '\\' in item_id:
        return False
    # Prevent malicious characters
    if not re.match(r'^[a-zA-Z0-9._-]+$', item_id):
        return False
    return True

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <config_file.xml>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        min_interval, services = load_config(config_path)
    except ValueError as e:
        print(f"Configuration error: {e}", file=sys.stderr)
        sys.exit(1)

    total_requests = 0
    total_bytes = 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 2:
            continue

        service_name, item_id = parts[0], parts[1]

        # Validate service name
        if service_name not in services:
            continue

        # Validate item_id
        if not is_valid_item_id(item_id):
            continue

        base_url = services[service_name]
        # Construct URL safely using urljoin to prevent path traversal
        request_url = urljoin(base_url, f"?item={item_id}")

        # Enforce rate limit after first request
        if total_requests > 0:
            time.sleep(min_interval)

        try:
            response = requests.get(request_url, timeout=10)
            status_code = response.status_code
            body_length = len(response.content)

            print(f"{service_name}\t{item_id}\t{status_code}\t{body_length}")

            total_requests += 1
            total_bytes += body_length

        except requests.exceptions.RequestException as e:
            # Log error without exposing details
            print(f"{service_name}\t{item_id}\t500\t0")
            total_requests += 1

    print(f"SUMMARY total_requests={total_requests} total_bytes={total_bytes}")

if __name__ == "__main__":
    main()

