import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_config(config_path):
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except FileNotFoundError:
        sys.exit(1)

    try:
        root = ET.fromstring(content)
        window_seconds = int(root.get('window_seconds'))
        clients = {}

        for client_elem in root.findall('client'):
            client_id = client_elem.get('id')
            max_active = int(client_elem.get('max_active'))
            max_new = int(client_elem.get('max_new'))
            tag = client_elem.get('tag')

            if not client_id or not tag:
                raise ValueError("Missing required client attributes")

            clients[client_id] = {
                'max_active': max_active,
                'max_new': max_new,
                'tag': tag
            }

        return window_seconds, clients
    except ET.ParseError as e:
        sys.exit(1)
    except ValueError as e:
        sys.exit(1)

def compute_signature(s):
    v = 0
    for c in s:
        u = ord(c)
        v = (v * 131 + u) % (2**64)
    return f"{v:016x}".lower()

def main():
    if len(sys.argv) != 2:
        print("Usage: alloc_throttle.py CONFIG.xml")
        sys.exit(1)

    config_path = sys.argv[1]
    window_seconds, clients = parse_config(config_path)

    # Initialize state for each client
    active_count = defaultdict(int)
    allocation_history = defaultdict(list)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 3:
            continue

        client_id, timestamp_str, action = parts
        timestamp = int(timestamp_str)

        # Validate client_id and action
        if not client_id or not action:
            print(f"UNKNOWN {client_id}")
            continue

        # Validate action
        if action not in ["ALLOCATE", "RELEASE"]:
            print(f"UNKNOWN {client_id}")
            continue

        # Validate timestamp is reasonable (within reasonable bounds)
        if timestamp < 0 or timestamp > 2**63 - 1:
            print(f"UNKNOWN {client_id}")
            continue

        # Check if client exists in config
        if client_id not in clients:
            print(f"UNKNOWN {client_id}")
            continue

        # Remove timestamps older than window_seconds ago
        window_bound = timestamp - window_seconds
        new_history = [t for t in allocation_history[client_id] if t >= window_bound]
        allocation_history[client_id] = new_history
        history_size = len(new_history)

        if action == "ALLOCATE":
            config = clients[client_id]
            current_active = active_count[client_id]

            # Check if allocation is allowed
            if current_active + 1 > config['max_active']:
                print(f"THROTTLED {client_id} {timestamp}")
                continue

            if history_size + 1 > config['max_new']:
                print(f"THROTTLED {client_id} {timestamp}")
                continue

            # Allocate resource
            active_count[client_id] += 1
            allocation_history[client_id].append(timestamp)
            signature = compute_signature(f"{client_id}|{timestamp}|ALLOCATE|{config['tag']}")
            print(f"ALLOCATED {client_id} {timestamp} {signature}")

        elif action == "RELEASE":
            current_active = active_count[client_id]
            if current_active > 0:
                active_count[client_id] -= 1
                signature = compute_signature(f"{client_id}|{timestamp}|RELEASE|{clients[client_id]['tag']}")
                print(f"RELEASED {client_id} {timestamp} {signature}")
            else:
                print(f"IGNORED {client_id} {timestamp}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import ast
import operator

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()

    limits_elem = root.find('limits')
    per_user_max = int(limits_elem.get('per_user_max', 0))

    variables = {}
    var_elems = root.find('variables')
    if var_elems is not None:
        for var_elem in var_elems.findall('var'):
            name = var_elem.get('name')
            value = var_elem.get('value')
            if name and value:
                variables[name] = float(value)

    return per_user_max, variables

def safe_eval_expression(expr, variables):
    # Define a safe set of allowed operations and values
    allowed_names = set(variables.keys())

    # Validate the expression using AST with strict node filtering
    try:
        # Parse the expression to ensure it's valid
        node = ast.parse(expr, mode='eval')

        # Validate the AST structure
        def validate_node(node):
            if isinstance(node, ast.Expression):
                node = node.body
            if isinstance(node, ast.Constant):
                return True
            if isinstance(node, ast.Num):
                return True
            if isinstance(node, ast.Str):
                return False  # Strings are not allowed
            if isinstance(node, ast.Name):
                name = node.id
                return name in allowed_names
            if isinstance(node, ast.BinOp):
                left = validate_node(node.left)
                right = validate_node(node.right)
                if not left or not right:
                    return False
                op = type(node.op).__name__
                if op not in ['Add', 'Sub', 'Mult', 'Div', 'Pow']:
                    return False
                return True
            if isinstance(node, ast.UnaryOp):
                if isinstance(node.op, (ast.USub, ast.UAdd)):
                    return validate_node(node.operand)
                return False
            if isinstance(node, ast.Call):
                return False  # No function calls allowed
            if isinstance(node, ast.Compare):
                return False  # No comparisons allowed
            if isinstance(node, ast.BoolOp):
                return False  # No boolean operations
            if isinstance(node, ast.List):
                return False  # No lists
            if isinstance(node, ast.Dict):
                return False  # No dictionaries
            if isinstance(node, ast.Tuple):
                return False  # No tuples
            if isinstance(node, ast.Attribute):
                return False  # No attributes
            if isinstance(node, ast.Subscript):
                return False  # No indexing
            return False
            return True

        # Validate the entire expression
        if not validate_node(node):
            return None

        # Replace variables in the expression with their values
        # We use a simple substitution for variables
        # We do not use eval or operator module to avoid security risks
        # Instead, we build a safe evaluation using only allowed operations

        # We'll use a recursive evaluation function that only uses allowed operations
        def evaluate_node(node):
            if isinstance(node, ast.Constant):
                return node.value
            if isinstance(node, ast.Num):
                return node.n
            if isinstance(node, ast.Name):
                name = node.id
                if name in variables:
                    return variables[name]
                return None
            if isinstance(node, ast.BinOp):
                left = evaluate_node(node.left)
                right = evaluate_node(node.right)
                if left is None or right is None:
                    return None
                op = node.op
                if isinstance(op, ast.Add):
                    return left + right
                elif isinstance(op, ast.Sub):
                    return left - right
                elif isinstance(op, ast.Mult):
                    return left * right
                elif isinstance(op, ast.Div):
                    if right == 0:
                        return None
                    return left / right
                elif isinstance(op, ast.Pow):
                    return left ** right
                return None
            if isinstance(node, ast.UnaryOp):
                operand = evaluate_node(node.operand)
                if operand is None:
                    return None
                op = node.op
                if isinstance(op, ast.USub):
                    return -operand
                elif isinstance(op, ast.UAdd):
                    return operand
                return None
            return None

        result = evaluate_node(node)
        if result is None:
            return None
        return result

    except Exception as e:
        return None

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    per_user_max, variables = parse_xml_config(xml_path)

    user_eval_count = {}

    try:
        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue

            parts = line.split(':', 1)
            if len(parts) != 2:
