            # Validate user_id: only allow alphanumeric and underscore, no colons or special characters
            if not all(c.isalnum() or c == '_' for c in user_id):
                print(f"ERROR {user_id}")
                continue

            # Check if user has reached the per-user limit
            if user_id in user_eval_count and user_eval_count[user_id] >= per_user_max:
                print(f"THROTTLED {user_id}")
                continue

            # Evaluate the expression safely
            result = safe_eval_expression(expression, variables)
            if result is None:
                print(f"ERROR {user_id}")
            else:
                user_eval_count[user_id] = user_eval_count.get(user_id, 0) + 1
                print(f"{user_id}: {result}")

